import { useEffect, useState, useRef } from "react";
import { useNavigate } from "react-router-dom";
import { MapContainer, TileLayer, Marker, Popup, useMapEvents } from "react-leaflet";
import "leaflet/dist/leaflet.css";
import L from "leaflet";
import { db } from "../firebase";
import { collection, getDocs, addDoc, doc, updateDoc, getDoc, setDoc } from "firebase/firestore";
import Navbar from "../components/Navbar"; // Importujemy Navbar
import "../styles/MapPage.css";

const CACHE_EXPIRY_TIME = 60 * 60 * 168 * 1000; // Czas ważności cache - 1 tydzień

// Naprawa problemu z ikoną markera w Leaflet
const defaultIcon = new L.Icon({
  iconUrl: "https://unpkg.com/leaflet@1.7.1/dist/images/marker-icon.png",
  iconSize: [25, 41],
  iconAnchor: [12, 41],
  popupAnchor: [1, -34],
  shadowUrl: "https://unpkg.com/leaflet@1.7.1/dist/images/marker-shadow.png",
  shadowSize: [41, 41],
});

export default function MapPage() {
  const navigate = useNavigate();
  const [locations, setLocations] = useState([]);
  const [newShop, setNewShop] = useState(null);
  const [shopName, setShopName] = useState("");
  const [rating, setRating] = useState(5);
  const [loading, setLoading] = useState(true);
  const shopNameRef = useRef(null);

  useEffect(() => {
    const getCachedData = () => {
      const cache = JSON.parse(localStorage.getItem("thriftShopsCache"));
      if (cache && new Date() - new Date(cache.timestamp) < CACHE_EXPIRY_TIME) {
        setLocations(cache.data);
        setLoading(false);
        return true;
      }
      return false;
    };

    const fetchShops = async () => {
      try {
        const [osmData, firestoreData] = await Promise.all([fetchOSMData(), fetchFirestoreData()]);
        const combinedData = [...osmData, ...firestoreData];
        setLocations(combinedData);
        localStorage.setItem("thriftShopsCache", JSON.stringify({ data: combinedData, timestamp: new Date().toISOString() }));
      } catch (error) {
        console.error("Błąd pobierania lumpeksów:", error);
      } finally {
        setLoading(false);
      }
    };

    if (!getCachedData()) {
      fetchShops();
    }
  }, []);

  // Pobieranie danych o lumpeksach z OpenStreetMap
  const fetchOSMData = async () => {
    const overpassUrl = `https://overpass-api.de/api/interpreter?data=[out:json];node["shop"="second_hand"](49.0,14.0,54.9,24.0);out;`;
    const response = await fetch(overpassUrl);
    const data = await response.json();
    return data.elements?.map(shop => ({
      id: String(shop.id),
      name: shop.tags.name || "Nieznany Sklep",
      lat: shop.lat,
      lng: shop.lon,
      ratings: [],
    })) || [];
  };

  // Pobieranie danych z Firestore
  const fetchFirestoreData = async () => {
    const querySnapshot = await getDocs(collection(db, "thriftShops"));
    return querySnapshot.docs.map(doc => ({ id: doc.id, ...doc.data() }));
  };

  function MapClickHandler() {
    useMapEvents({
      click: (e) => setNewShop({ lat: e.latlng.lat, lng: e.latlng.lng }),
    });
    return null;
  }

  // Sugestia nowego sklepu
  const handleSuggestShop = async (e) => {
    e.preventDefault();
    if (!shopName || !newShop) return alert("Podaj nazwę sklepu.");

    try {
      await addDoc(collection(db, "suggestedShops"), { name: shopName, lat: newShop.lat, lng: newShop.lng });
      setNewShop(null);
      setShopName("");
      alert("Sklep został zasugerowany!");
    } catch (error) {
      console.error("Błąd sugerowania sklepu:", error);
      alert("Nie udało się zasugerować sklepu.");
    }
  };

  // Dodawanie oceny sklepu
  const handleRate = async (e, shopId) => {
    e.preventDefault();
    try {
      const shop = locations.find(s => s.id === shopId);
      if (!shop) return alert("Nie znaleziono sklepu!");

      let newRatings = [...(shop.ratings || []), rating];
      const shopRef = doc(db, "thriftShops", String(shopId));

      const shopDoc = await getDoc(shopRef);

      if (!shopDoc.exists()) {
        await setDoc(shopRef, { id: String(shopId), name: shop.name, lat: shop.lat, lng: shop.lng, ratings: newRatings });
      } else {
        await updateDoc(shopRef, { ratings: newRatings });
      }

      setLocations(prev =>
        prev.map(s => (s.id === shopId ? { ...s, ratings: newRatings } : s))
      );

      alert("Dziękujemy za ocenę!");
    } catch (error) {
      console.error("Błąd oceniania sklepu:", error);
      alert("Nie udało się ocenić.");
    }
  };

  // Obliczanie średniej oceny sklepu
  const calculateAverageRating = (ratings) => {
    if (ratings.length === 0) return 0;
    const sum = ratings.reduce((acc, rating) => acc + rating, 0);
    return (sum / ratings.length).toFixed(1); // Zaokrąglamy do 1 miejsca po przecinku
  };

  useEffect(() => {
    shopNameRef.current?.focus();
  }, [shopName]);

  return (
    <div>
      <Navbar /> {/* Używamy komponentu Navbar */}
      
      {loading ? (
        <p>Ładowanie...</p>
      ) : (
        <MapContainer center={[52.2298, 21.0118]} zoom={6} className="map-container">
          <TileLayer url="https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png" />
          <MapClickHandler />

          {locations.map(shop => (
            <Marker key={shop.id} position={[shop.lat, shop.lng]} icon={defaultIcon}>
              <Popup className="popup-form">
                <h2>Oceń {shop.name}</h2>
                {shop.ratings && shop.ratings.length > 0 ? (
                  <p>Średnia ocena: {calculateAverageRating(shop.ratings)}</p>
                ) : (
                  <p>Brak ocen</p>
                )}
                <form onSubmit={(e) => handleRate(e, shop.id)} className="popup-form">
                  <input
                    type="range"
                    value={rating}
                    onChange={(e) => setRating(parseInt(e.target.value))}
                    max="5"
                    min="1"
                    required
                    className="rate-input"
                  />
                  <span>{rating}</span>
                  <button type="submit">Oceń Sklep</button>
                </form>
              </Popup>
            </Marker>
          ))}

          {newShop && (
            <Popup position={[newShop.lat, newShop.lng]} onClose={() => setNewShop(null)}>
              <form onSubmit={handleSuggestShop} className="popup-form">
                <h2>Zasugeruj Sklep</h2>
                <input
                  ref={shopNameRef}
                  type="text"
                  placeholder="Nazwa Sklepu"
                  value={shopName}
                  onChange={(e) => setShopName(e.target.value)}
                  required
                />
                <button type="submit">Zasugeruj Sklep</button>
              </form>
            </Popup>
          )}
        </MapContainer>
      )}
    </div>
  );
}
